var i=[{title:`Was sich in der Auszeit verändert`,text:`Aerobe Ausdauer, Bewegungsverträglichkeit und Hebeleistung lassen unterschiedlich schnell nach. Ein paar verpasste Tage machen vielleicht wenig Unterschied, während Wochen oder Monate ohne Training senken können, wie viel Arbeit du leisten kannst. Früheres Training kann dir helfen, Fertigkeiten schneller wieder zu lernen, aber „Muskelgedächtnis“ macht eine schrittweise Rückkehr nicht überflüssig.`},{title:`Warum du pausiert hast`,text:`Reisen oder ein voller Terminkalender sind etwas anderes als eine Verletzung, eine Operation oder eine lange Krankheit. Frage nach einem medizinischen Ereignis deine Ärztin, deinen Arzt oder eine andere geeignete Gesundheitsfachperson, bevor du zu hartem Training zurückkehrst. TrainUp kann nicht sagen, ob die Rückkehr nach einer Krankheit oder Verletzung für dich medizinisch sicher ist. Wenn sich etwas geändert hat, aktualisiere deine Einschränkungen im Profil, bevor du wieder anfängst.`},{title:`Ein vorsichtiger Startpunkt`,text:`Komme nach einer langen Pause mit weniger Sätzen, leichterem Widerstand und mehr Wiederholungen in Reserve zurück. Bei etwa 50–70 % deines früheren Trainingsumfangs zu beginnen ist ein Planungsbeispiel, das manchen Menschen passt; die Forschung legt diese Zahl nicht fest. Sieh, wie sich die ersten Einheiten anfühlen, bevor du Arbeit hinzufügst.`},{title:`In den folgenden Wochen aufbauen`,text:`Übe vertraute Techniken, lass genug Erholung und füge langsam Arbeit hinzu, während sich Bewegung und Muskelkater wieder normalisieren. Teste nicht sofort deine alten Maximalwerte. Wenn die erste Woche dich mit lang anhaltendem oder ungewöhnlich starkem Muskelkater zurücklässt, wiederhole oder kürze die Arbeitsbelastung, auch wenn dein Zeitplan sagt, dass es Zeit für die Steigerung ist.`}];var r=[{label:`NSCA/CSCCa: sichere Rückkehr nach Inaktivität`,url:`https://doi.org/10.1519/SSC.0000000000000477`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};